const oursIds = [...ours.matchAll(/^\s+id: "([^"]+)"/gm)].map((m) => m[1]);
console.log("HEAD ids:", headIds);
console.log("OURS ids:", oursIds);
console.log("separators in HEAD:", (head.match(/\n  \},\n  \{\n/g) || []).length);

