const after = text.slice(endLine); // starts with `  },\n  {\n    id: measurement...`

// If HEAD has multiple posts, first object fields are up to first `},\n  {`, rest are full objects.
const sep = "\n  },\n  {\n";
if (head.includes(sep)) {
  const parts = head.split(sep);
  // parts[0] = fields of first post (chokepoint)
  // parts[1..] = fields of subsequent posts
  const firstHeadFields = parts[0];
  const restHead = parts.slice(1).map((fields) => `  {\n${fields}`).join(",\n");
