  // where after starts with `  },\n  {\n measurement` ??? that closes last HEAD post and opens measurement. Perfect!

  let body = ours;
  body += sep + firstHeadFields;
  for (let i = 1; i < parts.length; i++) {
    body += sep + parts[i];
  }
  const resolved = before + body + "\n" + after;
  fs.writeFileSync(p, resolved);
  console.log("Resolved with multi-post HEAD insert");
} else {
  // Single HEAD post: ai-financing then HEAD post
  // before + ours + sep + head + after(with leading `},`)
  const resolved = before + ours + sep + head + "\n" + after;
  fs.writeFileSync(p, resolved);
  console.log("Resolved with single-post HEAD insert");
